use std::sync::{Arc, Mutex};

use mlua::{Function, StdLib, Value::Table, prelude::*};
use parking_lot::RwLock;
use tracing::{info, warn};

use crate::{
    connections::Update,
    packets::{Packet, Side, State, UnsureThreshold},
    scripts::{
        OwnType, Script,
        adaptations::{NbtBindings, UpdateBindings},
    },
};

const ENGINE_VERSION: u8 = 1;

const SIDES: usize = 2;
const STATES: usize = 4;

/// Builds the `s2c` / `c2s` namespaces: one table per protocol phase, each
/// holding the constructors generated by `#[derive(LuaPacket)]`.
///
/// The nesting mirrors the Rust enums, so a script writes
/// `s2c.play.ChatMessage { ... }` and gets the opcode from the variant's
/// `#[id(N)]` — never from the packet body, which would be wrong.
///
/// Every constructor is stamped with its `side` and `state`, so
/// [`Engine::register`] can read the opcode straight off the constructor the
/// script passes in instead of asking for a numeric id.
fn packet_bindings(lua: &Lua, side: Side) -> LuaResult<LuaTable> {
    let table = lua.create_table()?;
    let side_name: &'static str = side.into();

    // Binds one phase's constructors under `key`, stamping `state` on them.
    macro_rules! bind {
        ($key:literal, $state:literal, $module:path) => {
            table.set($key, <$module>::lua_bindings(lua, side_name, $state)?)?;
        };
    }

    match side {
        Side::S2C => {
            bind!(
                "handshake",
                "Handshake",
                crate::packets::s2c::handshake::Handshake
            );
            bind!("login", "Login", crate::packets::s2c::login::Login);
            bind!("play", "Play", crate::packets::s2c::play::Play);
            bind!("status", "Status", crate::packets::s2c::status::Status);
        }
        Side::C2S => {
            bind!(
                "handshake",
                "Handshake",
                crate::packets::c2s::handshake::Handshake
            );
            bind!("login", "Login", crate::packets::c2s::login::Login);
            bind!("play", "Play", crate::packets::c2s::play::Play);
            bind!("status", "Status", crate::packets::c2s::status::Status);
        }
    }
    Ok(table)
}

// Cheap to copy because Lua is Arc + bool
#[derive(Debug, Clone)]
pub struct Engine {
    handlers: Arc<RwLock<[Option<Handler>; 256 * SIDES * STATES]>>, // There is 2 sides and 4 states
    pub(crate) lua: Lua,
    pub(crate) script: Arc<Script>, // because Script is heavy
}

impl Engine {
    pub fn new(script: Arc<Script>) -> LuaResult<Self> {
        let lua = Lua::new_with(
            StdLib::BIT | StdLib::MATH | StdLib::STRING | StdLib::TABLE,
            LuaOptions::default(),
        )?;

        Ok(Self {
            handlers: Arc::new(RwLock::new([const { None }; 256 * 2 * 4])),
            lua,
            script,
        })
    }

    pub fn set_globals(&self) -> LuaResult<()> {
        self.lua.globals().set("engine", self.clone())?;
        self.lua.globals().set("update", UpdateBindings)?;
        self.lua.globals().set("nbt", NbtBindings)?;
        self.lua
            .globals()
            .set("s2c", packet_bindings(&self.lua, Side::S2C)?)?;
        self.lua
            .globals()
            .set("c2s", packet_bindings(&self.lua, Side::C2S)?)?;

        self.add_sleep()?;
        self.add_print()?;
        self.add_require()?;

        Ok(())
    }

    pub async fn run(&self, code: &str) -> LuaResult<()> {
        info!("Loading script \"{}\"", self.script.name);
        info!("{}", self.script.description);
        match self.script.engine_version {
            ver if ver < ENGINE_VERSION => {
                return Err(LuaError::external(format!(
                    "The engine is outdated: the script is for engine v{}, current version is {}",
                    self.script.engine_version, ENGINE_VERSION
                )));
            }
            ver if ver > ENGINE_VERSION => warn!(
                "The script is outdated: the script is for engine v{}, current version is {}",
                self.script.engine_version, ENGINE_VERSION
            ),
            _ => {}
        };
        self.lua.load(code).exec_async().await
    }

    fn calc_index(packet_id: u8, side: Side, state: State) -> usize {
        let state_id = u8::try_from(state).unwrap() as usize;
        let side_id = u8::try_from(side).unwrap() as usize;
        (side_id * 256) + (state_id * 256 * SIDES) + packet_id as usize
    }

    pub fn parse_packet_id(state: State, side: Side, packet: LuaValue) -> LuaResult<u8> {
        Ok(match packet {
            // A constructor table: read the metadata the derive stamped on it.
            LuaValue::Table(ref constructor) => {
                let opcode: i32 = constructor.get("opcode")?;
                let packet_id = u8::try_from(opcode).map_err(|_| {
                    LuaError::runtime(format!("packet opcode {opcode} does not fit in a u8"))
                })?;

                // The constructor knows its own side and state; a mismatch means
                // the script registered it under the wrong phase, which would
                // never fire. Report it rather than silently doing nothing.
                if let Some(constructor_side) = constructor.get::<Option<String>>("side")? {
                    let constructor_side =
                        Side::try_from(constructor_side.as_str()).map_err(LuaError::runtime)?;
                    if constructor_side != side {
                        return Err(LuaError::runtime(format!(
                            "packet is a {} packet, but it was registered as {}",
                            <&'static str>::from(constructor_side),
                            <&'static str>::from(side),
                        )));
                    }
                }
                if let Some(constructor_state) = constructor.get::<Option<String>>("state")? {
                    let constructor_state =
                        State::try_from(constructor_state.as_str()).map_err(LuaError::runtime)?;
                    if constructor_state != state {
                        return Err(LuaError::runtime(format!(
                            "packet belongs to the {constructor_state:?} state, but it was registered as {state:?}",
                        )));
                    }
                }

                packet_id
            }
            // Backwards compatibility: a bare opcode.
            LuaValue::Integer(opcode) => u8::try_from(opcode).map_err(|_| {
                LuaError::runtime(format!("packet opcode {opcode} does not fit in a u8"))
            })?,
            other => {
                return Err(LuaError::runtime(format!(
                    "expected a packet constructor (e.g. s2c.play.SetEntityMetadata), got {}",
                    other.type_name()
                )));
            }
        })
    }

    /// Registers a handler for one packet.
    ///
    /// `packet` is a constructor from the `s2c` / `c2s` namespaces, e.g.
    /// `s2c.play.SetEntityMetadata`. The opcode, side and state are read off
    /// that constructor, so a script never has to hard-code a numeric id:
    ///
    /// ```lua
    /// engine:register("Play", "S2C", s2c.play.SetEntityMetadata, "read", handler)
    /// ```
    ///
    /// The `state` and `side` arguments are still accepted (and checked against
    /// the constructor) so a typo is reported instead of silently registering
    /// the handler under the wrong phase. A plain integer is also accepted for
    /// backwards compatibility.
    fn register(&self, register_options: RegisterOptions) -> LuaResult<()> {
        let packet_id = Self::parse_packet_id(register_options.state, register_options.side, register_options.packet)?;
        let key = self.lua.create_registry_value(register_options.function)?;

        self.handlers.write()[Self::calc_index(packet_id, register_options.side, register_options.state)] = Some(Handler {
            key,
            own_type: register_options.own_type,
            is_blocking: register_options.is_blocking,
        });
        Ok(())
    }

    pub fn get_func(
        &self,
        packet_id: u8,
        state: State,
        side: Side,
        own_type: OwnType,
    ) -> LuaResult<Option<FunctionData>> {
        let handlers = self.handlers.read();
        let Some(ref handler) = handlers[Self::calc_index(packet_id, side, state)] else {
            return Ok(None);
        };
        if handler.own_type != own_type {
            return Ok(None);
        };
        Ok(Some(FunctionData {
            function: self.lua.registry_value(&handler.key)?,
            is_blocking: handler.is_blocking,
        }))
    }

    pub async fn on_packet(
        &self,
        func: Function,
        own_type: OwnType,
        packet_id: u8,
        options: HandlerOptions<'_>,
    ) -> LuaResult<Option<Option<Update>>> {
        let result = func.call_async::<Option<Update>>(options).await?;
        Ok(Some(match (result, own_type) {
            // Returning nothing means "leave the packet alone" and is always allowed.
            (None, _) => None,

            // Read-only must not touch the packet in any way.
            (Some(_), OwnType::ReadOnly) => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read\" but returned an Update"
                )));
            }

            // Read-write may replace, but not inject into the other direction.
            (Some(update), OwnType::ReadWrite) if update.inject.is_some() => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read-write\" but returned an inject"
                )));
            }
            (Some(update), OwnType::ReadWrite) => Some(update),

            // Read-inject may inject, but not replace.
            (Some(update), OwnType::ReadInject) if update.change_with.is_some() => {
                return Err(LuaError::runtime(format!(
                    "handler for packet {packet_id} is registered as \"read-inject\" but returned a change_with"
                )));
            }
            (Some(update), OwnType::ReadInject) => Some(update),

            // Full rights: anything goes.
            (Some(update), OwnType::ReadWriteInject) => Some(update),
        }))
    }
}

impl LuaUserData for Engine {
    fn add_methods<M: LuaUserDataMethods<Self>>(methods: &mut M) {
        methods.add_method_mut(
            "register",
            |lua,
             this,
             options: LuaValue| {
                /*
                (state, side, packet, own_type, is_blocking, func): (
                    String,
                    String,
                    LuaValue,
                    String,
                    bool,
                    Function,
                )| {
                */
                let register_options = RegisterOptions::from_lua(options, lua)?;
                this.register(register_options)
            },
        );
    }
}

pub struct RegisterOptions {
    pub state: State,
    pub side: Side,
    pub packet: LuaValue,
    pub own_type: OwnType,
    pub is_blocking: bool,
    pub function: Function,
}

impl FromLua for RegisterOptions {
    fn from_lua(value: LuaValue, _lua: &Lua) -> LuaResult<Self> {
        let Table(table) = value else {
            return Err(LuaError::runtime("Invalid options type, expected Table"));
        };
        let state: String = table.get("state")?;
        let side: String = table.get("side")?;
        let packet: LuaValue = table.get("packet")?;
        let own_type: String = table.get("own_type")?;
        let is_blocking: bool = table.get("is_blocking")?;
        let function: Function = table.get("function")?;
        Ok(Self {
            state: State::try_from(state.as_str()).map_err(|e| LuaError::runtime(e))?,
            side: Side::try_from(side.as_str()).map_err(|e| LuaError::runtime(e))?,
            packet,
            own_type: OwnType::try_from(own_type.as_str()).map_err(|e| LuaError::runtime(e))?,
            is_blocking,
            function
        })
    }
}

pub struct FunctionData {
    pub function: Function,
    pub is_blocking: bool,
}

pub struct HandlerOptions<'a> {
    pub packet: &'a Packet<'a>,
    pub threshold: &'a UnsureThreshold,
    pub is_injected: bool,
}

impl<'a> HandlerOptions<'a> {
    pub fn new(packet: &'a Packet<'a>, threshold: &'a UnsureThreshold, is_injected: bool) -> Self {
        Self {
            packet,
            threshold,
            is_injected,
        }
    }
}

impl IntoLua for HandlerOptions<'_> {
    fn into_lua(self, lua: &Lua) -> LuaResult<LuaValue> {
        let table = lua.create_table()?;
        table.set("packet", self.packet)?;
        table.set("threshold", self.threshold)?;
        table.set("is_injected", self.is_injected)?;
        Ok(LuaValue::Table(table))
    }
}

#[derive(Debug)]
pub struct Handler {
    key: LuaRegistryKey,
    own_type: OwnType,
    is_blocking: bool,
}
